# solution (verified locally): add to tests/test_ot.py
def retained_positions(op: TextOp) -> list[int]:
    out, i = [], 0
    for c in op.ops:
        if isinstance(c, int) and c > 0:
            out.extend(range(i, i + c))
            i += c
        elif isinstance(c, int):          # delete
            i += -c
    return out


@pytest.mark.parametrize("seed", range(5))
def test_property_transform_index_tracks_retained_chars(seed):
    rng = random.Random(500 + seed)
    for _ in range(400):
        doc = random_doc(rng)
        op = random_op(doc, rng)
        new = apply(doc, op)
        for i in retained_positions(op):
            assert new[transform_index(op, i)] == doc[i], (doc, op.ops, i)

# solution (verified locally): collab/ot.py
def invert(op: TextOp, doc: str) -> TextOp:
    """Inverse of op, given the document op was applied to: apply(apply(doc, op), invert(op, doc)) == doc."""
    inv, i = TextOp(), 0
    for c in op.ops:
        if is_retain(c):
            inv.retain(c)
            i += c
        elif is_insert(c):
            inv.delete(len(c))
        else:
            inv.insert(doc[i:i - c])      # c < 0: the text it deleted
            i -= c
    return inv

