@pytest.mark.parametrize("seed", range(5))
def test_property_invert_undoes(seed):
    rng = random.Random(900 + seed)
    for _ in range(400):
        doc = random_doc(rng)
        op = random_op(doc, rng)
        assert apply(apply(doc, op), invert(op, doc)) == doc
